sys_script_include.script:
var BaseVagasUtil = Class.create();
BaseVagasUtil.prototype = {

    // Story 7 — filters bases with available spots
    getAvailableBases: function() {
        var availableBases = [];

        var baseGR = new GlideRecord('x_1902784_base_a_0_base_registration');
        baseGR.query();

        while (baseGR.next()) {
            var baseId = baseGR.getUniqueValue();
            var maxCapacity = parseInt(baseGR.getValue('max_capacity'), 10);

            if (!maxCapacity || maxCapacity <= 0) continue;

            var allocationGR = new GlideAggregate('x_1902784_base_a_0_base_allocation');
            allocationGR.addQuery('base', baseId);
            var stateQuery = allocationGR.addQuery('state', '2');
            stateQuery.addOrCondition('state', '3');
            allocationGR.addAggregate('COUNT');
            allocationGR.query();

            var count = 0;
            if (allocationGR.next()) {
                count = parseInt(allocationGR.getAggregate('COUNT'), 10);
            }

            if (count < maxCapacity) {
                availableBases.push(baseId);
            }
        }

        if (availableBases.length === 0) return 'sys_id=NULL';

        return 'sys_idIN' + availableBases.join(',');
    },

    // Story 8 — blocks user with active registration
    canRegister: function(userId) {
        var allocationGR = new GlideRecord('x_1902784_base_a_0_base_allocation');
        //allocationGR.addQuery('gs.getUserID');
        allocationGR.addQuery('opened_by', gs.getUserID());
        var stateQuery = allocationGR.addQuery('state', '1');
        stateQuery.addOrCondition('state', '2');
        stateQuery.addOrCondition('state', '3');
        allocationGR.query();

        if (allocationGR.next()) return 'sys_id=NULL';

        return this.getAvailableBases();
    },

    type: 'BaseVagasUtil'
};
